@Entity
@Table(name = "books")
public class Book {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String title;
    private String isbn;
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "author_id")
    private Author author;

    private int copiesTotal;
    private int copiesAvailable;

    @Version
    private long version;

    protected Book() {
        // required by JPA
    }

    public Book(String title, String isbn, Author author, int copies) {
        this.title = title;
        this.isbn = isbn;
        this.author = author;
        this.copiesTotal = copies;
        this.copiesAvailable = copies;
    }

    public void update(String title, String isbn, Author author) {
        this.title = title;
        this.isbn = isbn;
        this.author = author;
    }

    public void checkOut() {
        if (copiesAvailable == 0) {
            throw new ConflictException("No copy of '" + title + "' is available");
        }
        copiesAvailable--;
    }

    public void checkIn() {
        if (copiesAvailable >= copiesTotal) {
            throw new ConflictException("All copies of '" + title + "' are already in");
        }
        copiesAvailable++;
    }

    public Long getId() { return id; }
    public String getTitle() { return title; }
    public String getIsbn() { return isbn; }
    public Author getAuthor() { return author; }
    public int getCopiesTotal() { return copiesTotal; }
    public int getCopiesAvailable() { return copiesAvailable; }
}

