package com.example.library.service;

import com.example.library.domain.Author;
import com.example.library.domain.Book;
import com.example.library.error.ConflictException;
import com.example.library.error.NotFoundException;
import com.example.library.repository.AuthorRepository;
import com.example.library.repository.BookRepository;
import com.example.library.repository.LoanRepository;
import com.example.library.web.dto.BookRequest;
import com.example.library.web.dto.BookResponse;
import com.example.library.web.dto.OtherDtos.PageResponse;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class BookService {

    private final BookRepository books;
    private final AuthorRepository authors;
    private final LoanRepository loans;

    public BookService(BookRepository books, AuthorRepository authors, LoanRepository loans) {
        this.books = books;
        this.authors = authors;
        this.loans = loans;
    }

    public PageResponse<BookResponse> search(String title, Pageable pageable) {
        String q = title == null ? "" : title;
        return PageResponse.of(books.findByTitleContainingIgnoreCase(q, pageable)
                .map(BookResponse::from));
    }

    public BookResponse get(long id) {
        return BookResponse.from(find(id));
    }

    @Transactional
    public BookResponse create(BookRequest req) {
        if (books.existsByIsbn(req.isbn())) {
            throw new ConflictException("ISBN " + req.isbn() + " already exists");
        }
        Book saved = books.save(new Book(req.title(), req.isbn(), author(req.authorId()),
                req.copies()));
        return BookResponse.from(saved);
    }

    @Transactional
    public BookResponse update(long id, BookRequest req) {
        Book book = find(id);
        if (!book.getIsbn().equals(req.isbn()) && books.existsByIsbn(req.isbn())) {
            throw new ConflictException("ISBN " + req.isbn() + " already exists");
        }
        book.update(req.title(), req.isbn(), author(req.authorId()));
        return BookResponse.from(book);   // dirty checking writes the UPDATE at commit
    }

    @Transactional
    public void delete(long id) {
        Book book = find(id);
        if (loans.existsByBookId(id)) {
            throw new ConflictException("Book " + id + " has loans and cannot be deleted");
        }
        books.delete(book);
    }

    private Book find(long id) {
        return books.findById(id).orElseThrow(() -> new NotFoundException("Book", id));
    }
    private Author author(long id) {
        return authors.findById(id).orElseThrow(() -> new NotFoundException("Author", id));
    }
}

package com.example.library.service;

import com.example.library.domain.Book;
import com.example.library.domain.Loan;
import com.example.library.error.ConflictException;
import com.example.library.error.NotFoundException;
import com.example.library.repository.BookRepository;
import com.example.library.repository.LoanRepository;
import com.example.library.web.dto.OtherDtos.LoanResponse;
import java.time.Clock;
import java.time.LocalDate;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class LoanService {

    static final int LOAN_DAYS = 14;

    private final LoanRepository loans;
    private final BookRepository books;
    private final Clock clock;

    public LoanService(LoanRepository loans, BookRepository books, Clock clock) {
        this.loans = loans;
        this.books = books;
        this.clock = clock;
    }

    @Transactional
    public LoanResponse borrow(long bookId, String borrower) {
        Book book = books.findById(bookId)
                .orElseThrow(() -> new NotFoundException("Book", bookId));
        book.checkOut();                                  // throws ConflictException if none left
        LocalDate today = LocalDate.now(clock);
        Loan loan = loans.save(new Loan(book, borrower, today, today.plusDays(LOAN_DAYS)));
        return LoanResponse.from(loan);
    }

    @Transactional
    public LoanResponse giveBack(long loanId) {
        Loan loan = loans.findById(loanId)
                .orElseThrow(() -> new NotFoundException("Loan", loanId));
        if (loan.isReturned()) {
            throw new ConflictException("Loan " + loanId + " was already returned");
        }
        loan.markReturned(LocalDate.now(clock));
        loan.getBook().checkIn();
        return LoanResponse.from(loan);
    }

    public List<LoanResponse> mine(String borrower) {
        return loans.findByBorrowerOrderByLoanedAtDesc(borrower).stream()
                .map(LoanResponse::from).toList();
    }
    public List<LoanResponse> all() {
        return loans.findAllByOrderByLoanedAtDesc().stream().map(LoanResponse::from).toList();
    }
}

