import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.example.library.domain.Author;
import com.example.library.domain.Book;
import com.example.library.domain.Loan;
import com.example.library.error.ConflictException;
import com.example.library.repository.BookRepository;
import com.example.library.repository.LoanRepository;
import com.example.library.web.dto.OtherDtos.LoanResponse;
import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class LoanServiceTest {

    @Mock
    LoanRepository loans;

    @Mock
    BookRepository books;

    LoanService service;

    @BeforeEach
    void setUp() {
        Clock clock = Clock.fixed(Instant.parse("2026-03-01T10:00:00Z"), ZoneOffset.UTC);
        service = new LoanService(loans, books, clock);
    }

    @Test
    void borrowTakesACopyAndSetsDueDate() {
        Book book = new Book("Dune", "978-0441172719", new Author("Frank Herbert"), 2);
        when(books.findById(1L)).thenReturn(Optional.of(book));
        when(loans.save(any(Loan.class))).thenAnswer(inv -> inv.getArgument(0));

        LoanResponse loan = service.borrow(1L, "alice");

        assertThat(book.getCopiesAvailable()).isEqualTo(1);
        assertThat(loan.dueDate()).isEqualTo(LocalDate.of(2026, 3, 15));
        assertThat(loan.borrower()).isEqualTo("alice");
    }

    @Test
    void borrowFailsWhenNoCopyIsLeft() {
        Book book = new Book("Dune", "978-0441172719", new Author("Frank Herbert"), 1);
        book.checkOut();
        when(books.findById(1L)).thenReturn(Optional.of(book));

        assertThatThrownBy(() -> service.borrow(1L, "alice"))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("Dune");
        verify(loans, never()).save(any());
    }
}

